*{box-sizing:border-box} :root{--ink:#f4f0e5;--muted:#a9aa9f;--cream:#e9dfc9;--orange:#c8794c;--dark:#17211d;--line:rgba(242,238,222,.18)}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#899378;color:var(--ink);font-family:'DM Sans',sans-serif}button,select{font:inherit}#game-shell{position:relative;width:100%;height:100%;min-height:520px;overflow:hidden;background:#9ba187}canvas#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(13,23,19,.52),transparent 25%,transparent 68%,rgba(13,21,17,.42)),linear-gradient(90deg,rgba(11,20,16,.22),transparent 50%,rgba(11,20,16,.14)}.topbar{position:absolute;top:0;left:0;right:0;height:78px;padding:0 4.1%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.15);z-index:2}.wordmark{display:flex;gap:12px;align-items:center;color:#fff;text-decoration:none;font-size:13px;font-weight:800;letter-spacing:.16em}.mark{width:29px;height:29px;border:1px solid rgba(255,255,255,.7);display:grid;place-items:center;font-family:Georgia,serif;font-size:20px;font-style:italic;font-weight:400;letter-spacing:0}.word-light{font-weight:400;opacity:.72}.top-center{display:flex;gap:14px;align-items:center;font:10px 'DM Mono',monospace;letter-spacing:.14em;color:rgba(255,255,255,.8)}.top-center i{height:13px;width:1px;background:rgba(255,255,255,.4)}.live-dot,.garage-status i{width:6px;height:6px;background:#d4c194;border-radius:50%;display:inline-block}.icon-btn{width:38px;height:38px;border:1px solid rgba(255,255,255,.35);background:rgba(23,33,29,.18);color:#fff;font-size:21px;cursor:pointer}.sliders{font-size:20px;line-height:1}.hud{position:absolute;inset:90px 4.1% auto;display:none;align-items:flex-start;justify-content:space-between;pointer-events:none}.hud.active{display:flex}.speed-card{width:178px;padding:17px 19px;background:rgba(23,33,29,.74);backdrop-filter:blur(8px);border:1px solid rgba(255,255,255,.14)}.speed-row{display:flex;align-items:baseline;gap:8px}.speed-number{font-size:44px;line-height:1;font-weight:500;letter-spacing:-.05em;font-variant-numeric:tabular-nums}.speed-unit{font:10px 'DM Mono',monospace;color:#c5c6b8;letter-spacing:.14em}.speed-rule{height:2px;background:rgba(255,255,255,.18);margin:12px 0 11px}.speed-rule span{display:block;width:0;height:2px;background:#d6b485;transition:width .2s}.gear-row{display:flex;justify-content:space-between;font:9px 'DM Mono',monospace;letter-spacing:.14em;color:#d4c6a9}.gear-row span:first-child{color:#fff}.location-card{display:flex;gap:11px;align-items:center;background:rgba(23,33,29,.64);padding:11px 15px;border:1px solid rgba(255,255,255,.13);backdrop-filter:blur(8px)}.location-icon{font-size:25px;color:#dac49c}.eyebrow{font:9px 'DM Mono',monospace;letter-spacing:.17em;color:#c7c7b9}.location-name{font-size:13px;font-weight:700;letter-spacing:.12em;margin:4px 0 3px}.location-sub{font:8px 'DM Mono',monospace;letter-spacing:.1em;color:#b1b5a8}.minimap{width:112px;height:112px;position:relative;border:1px solid rgba(255,255,255,.35);background:rgba(29,42,35,.76);overflow:hidden}.map-grid{position:absolute;inset:0;background-image:linear-gradient(rgba(230,220,192,.07) 1px,transparent 1px),linear-gradient(90deg,rgba(230,220,192,.07) 1px,transparent 1px);background-size:18px 18px}.minimap svg{width:100%;height:100%;position:absolute}.map-road{fill:none;stroke:#d6ceb7;stroke-width:3}.map-road-secondary{fill:none;stroke:#c7b99b;stroke-width:2;opacity:.65}.map-player{fill:#d28a5c;stroke:#fff2da;stroke-width:2}.map-north{position:absolute;right:7px;top:5px;font:8px 'DM Mono',monospace;color:#d6ceb7}.controls-hint{position:absolute;bottom:30px;left:50%;transform:translateX(-50%);align-items:center;display:none;gap:6px;background:rgba(21,30,26,.76);border:1px solid rgba(255,255,255,.17);padding:9px 13px;color:rgba(255,255,255,.72);font:8px 'DM Mono',monospace;letter-spacing:.12em;white-space:nowrap;backdrop-filter:blur(5px)}.controls-hint.active{display:flex}.key{height:20px;min-width:21px;padding:0 5px;display:inline-grid;place-items:center;border:1px solid rgba(255,255,255,.4);border-radius:2px;color:#fff;font:9px 'DM Mono',monospace}.key-stack{display:flex;gap:2px}.key-stack .key{height:19px;min-width:19px}.hint-copy{margin:0 4px}.hint-divider{height:17px;width:1px;background:rgba(255,255,255,.22);margin:0 5px}.toast{position:absolute;top:103px;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.3s;background:rgba(24,34,29,.9);padding:10px 17px;border:1px solid rgba(255,255,255,.22);font:9px 'DM Mono',monospace;letter-spacing:.13em;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.garage-screen{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:center;padding:7.8% 8.3% 3.2%;background:linear-gradient(90deg,rgba(19,28,24,.93) 0%,rgba(19,28,24,.86) 32%,rgba(19,28,24,.32) 64%,rgba(19,28,24,.08) 100%),linear-gradient(0deg,rgba(18,26,22,.58),transparent 36%);z-index:3;transition:opacity .55s,visibility .55s}.garage-screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.garage-panel{height:100%;max-height:660px;display:grid;grid-template-columns:37% 63%;border:1px solid rgba(236,226,204,.25);background:rgba(21,29,25,.6);box-shadow:0 20px 70px rgba(8,13,10,.23);backdrop-filter:blur(5px)}.garage-left{padding:42px 44px 25px;position:relative;display:flex;flex-direction:column;border-right:1px solid rgba(236,226,204,.22)}.warm{color:#d5a77f}.eyebrow-line{display:inline-block;vertical-align:middle;width:31px;height:1px;background:#c8794c;margin-left:10px}.garage-left h1{font-size:clamp(39px,5.25vw,73px);line-height:.93;letter-spacing:-.065em;font-weight:500;margin:24px 0 19px}.garage-left h1 em,.settings-card h2 em{font-family:Georgia,serif;font-weight:400;color:#d3b18d;letter-spacing:-.07em}.intro{font-size:12px;line-height:1.75;color:#c4c6b9;margin:0 0 auto}.car-info{margin-top:24px}.car-index{font:10px 'DM Mono',monospace;color:#d4a47b;letter-spacing:.1em}.car-index small{color:#83897d}.car-name{font-size:18px;font-weight:700;letter-spacing:.09em;margin-top:8px}.car-description{font-size:11px;color:#aeb3a7;margin-top:5px}.car-picker{display:flex;gap:8px;margin:17px 0 16px}.car-option{width:36px;height:34px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.19);color:#c6c7bb;cursor:pointer;font:10px 'DM Mono',monospace;transition:.2s}.car-option:hover,.car-option.active{border-color:#d09a70;background:rgba(197,119,75,.18);color:white}.drive-button{height:49px;display:flex;justify-content:space-between;align-items:center;padding:0 18px;border:0;background:#c8794c;color:#fff;cursor:pointer;font-size:10px;letter-spacing:.17em;font-weight:700;transition:.2s}.drive-button:hover{background:#d58d60;transform:translateY(-1px)}.drive-button b{font-size:19px;font-weight:400}.garage-foot{display:flex;justify-content:space-between;color:#8f988c;font:8px 'DM Mono',monospace;letter-spacing:.11em;margin-top:18px}.garage-right{position:relative;overflow:hidden;background:linear-gradient(135deg,rgba(188,178,148,.06),transparent 55%)}.garage-right:before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at 55% 61%,rgba(217,193,153,.18),transparent 44%)}.garage-right-top{position:absolute;top:26px;left:30px;right:30px;display:flex;justify-content:space-between;align-items:center}.garage-status{font:8px 'DM Mono',monospace;letter-spacing:.12em;color:#d9d4c4}.garage-status i{width:5px;height:5px;background:#9eaa82;margin-right:8px}.car-shadow{position:absolute;left:10%;right:5%;top:24%;height:69%;background:radial-gradient(ellipse,rgba(2,8,6,.47),transparent 61%);filter:blur(14px)}.garage-note{position:absolute;left:8%;top:50%;display:flex;align-items:center;gap:9px;transform:rotate(-90deg) translateX(-50%);transform-origin:top left;color:rgba(239,231,211,.62);font:8px 'DM Mono',monospace;letter-spacing:.17em}.note-line{display:inline-block;width:28px;height:1px;background:#c8794c}.garage-bottom{position:absolute;bottom:25px;left:30px;right:30px;display:flex;align-items:center;justify-content:space-between;color:#bdc0b3;font:8px 'DM Mono',monospace;letter-spacing:.12em}.swatches{display:flex;gap:7px}.swatch{width:12px;height:12px;border:1px solid rgba(255,255,255,.5);border-radius:50%;cursor:pointer}.garage-footer{display:flex;justify-content:space-between;color:rgba(241,235,219,.6);font:8px 'DM Mono',monospace;letter-spacing:.13em;margin-top:13px}.settings-modal{position:absolute;inset:0;z-index:6;background:rgba(10,16,13,.63);display:grid;place-items:center;opacity:0;visibility:hidden;transition:.25s;backdrop-filter:blur(5px)}.settings-modal.open{opacity:1;visibility:visible}.settings-card{position:relative;width:min(460px,calc(100% - 34px));padding:38px;background:#1c2822;border:1px solid rgba(235,224,198,.24);box-shadow:0 20px 80px #080d0a}.close-button{position:absolute;right:18px;top:14px;border:0;background:transparent;color:#d8d6ca;font-size:26px;cursor:pointer}.settings-card h2{font-size:38px;line-height:.95;letter-spacing:-.05em;font-weight:500;margin:17px 0 30px}.setting-row{display:flex;align-items:center;justify-content:space-between;border-top:1px solid rgba(255,255,255,.14);padding:17px 0}.setting-row strong{display:block;font-size:12px;font-weight:600}.setting-row small{display:block;color:#a8afa2;font-size:10px;margin-top:5px}.setting-row select{background:#29372f;color:#f0ede1;border:1px solid rgba(255,255,255,.25);padding:8px 26px 8px 10px;font-size:11px;outline:none}.toggle{width:37px;height:21px;border-radius:99px;background:#596159;border:0;padding:3px;cursor:pointer}.toggle span{width:15px;height:15px;border-radius:50%;display:block;background:#e6e1d4;transition:.2s}.toggle.on{background:#a96c49}.toggle.on span{transform:translateX(16px)}.settings-note{font:10px 'DM Mono',monospace;color:#aaaFA1;border-top:1px solid rgba(255,255,255,.14);padding-top:17px;margin-top:5px}.pause-chip{position:absolute;display:none;z-index:4;left:50%;top:50%;transform:translate(-50%,-50%);padding:17px 23px;background:rgba(23,33,29,.88);border:1px solid rgba(255,255,255,.2);font:10px 'DM Mono',monospace;letter-spacing:.15em}.pause-chip.show{display:flex;align-items:center;gap:11px}.pause-chip span{color:#d09a70}.pause-chip button{margin-left:10px;padding:7px 10px;border:1px solid rgba(255,255,255,.35);background:transparent;color:#fff;font:9px 'DM Mono',monospace;letter-spacing:.1em;cursor:pointer}
@media(max-width:850px){.topbar{height:62px;padding:0 18px}.top-center{font-size:8px;gap:8px}.garage-screen{padding:76px 17px 17px}.garage-panel{grid-template-columns:1fr;height:100%;max-height:none;overflow:hidden}.garage-left{padding:25px 24px 18px;border-right:0;background:linear-gradient(90deg,rgba(20,29,25,.94),rgba(20,29,25,.79));z-index:1}.garage-left h1{font-size:clamp(40px,10vw,64px);margin:14px 0 12px}.intro{font-size:11px}.car-info{margin-top:14px}.car-picker{margin:11px 0}.drive-button{height:44px}.garage-right{position:absolute;inset:0 0 0 31%;opacity:.85}.garage-right-top{top:15px;left:auto;right:18px}.garage-right-top>.eyebrow{display:none}.garage-note{display:none}.garage-bottom{bottom:15px;left:auto;right:18px;flex-direction:column;gap:8px;align-items:flex-end}.garage-footer{font-size:7px}.garage-foot{margin-top:12px}.hud{inset:75px 14px auto}.speed-card{width:145px;padding:13px}.speed-number{font-size:36px}.minimap{width:86px;height:86px}.location-card{position:absolute;top:100px;left:0;padding:9px}.controls-hint{bottom:12px;transform:translateX(-50%) scale(.9);transform-origin:bottom center}.top-center span:last-child,.top-center i{display:none}}
@media(max-height:650px){.garage-screen{padding-top:66px;padding-bottom:15px}.garage-left{padding-top:24px;padding-bottom:15px}.garage-left h1{font-size:clamp(34px,4.5vw,58px);margin:13px 0}.intro{font-size:10px}.car-info{margin-top:12px}.car-picker{margin:9px 0}.garage-foot{margin-top:10px}.garage-footer{margin-top:8px}}

