display:inline-block;width:28px;height:1px;background:#c8794c}.garage-bottom{position:absolute;bottom:25px;left:30px;right:30px;display:flex;align-items:center;justify-content:space-between;color:#bdc0b3;font:8px 'DM Mono',monospace;letter-spacing:.12em}.swatches{display:flex;gap:7px}.swatch{width:12px;height:12px;border:1px solid rgba(255,255,255,.5);border-radius:50%;cursor:pointer}.garage-footer{display:flex;justify-content:space-between;color:rgba(241,235,219,.6);font:8px 'DM Mono',monospace;letter-spacing:.13em;margin-top:13px}.settings-modal{position:absolute;inset:0;z-index:6;background:rgba(10,16,13,.63);display:grid;place-items:center;opacity:0;visibility:hidden;transition:.25s;backdrop-filter:blur(5px)}.settings-modal.open{opacity:1;visibility:visible}.settings-card{position:relative;width:min(460px,calc(100% - 34px));padding:38px;background:#1c2822;border:1px solid rgba(235,224,198,.24);box-shadow:0 20px 80px #080d0a}.close-button{position:absolute;right:18px;top:14px;border:0;background:transparent;color:#d8d6ca;font-size:26px;cursor:pointer}.settings-card h2{font-size:38px;line-height:.95;letter-spacing:-.05em;font-weight:500;margin:17px 0 30px}.setting-row{display:flex;align-items:center;justify-content:space-between;border-top:1px solid rgba(255,255,255,.14);padding:17px 0}.setting-row strong{display:block;font-size:12px;font-weight:600}.setting-row small{display:block;color:#a8afa2;font-size:10px;margin-top:5px}.setting-row select{background:#29372f;color:#f0ede1;border:1px solid rgba(255,255,255,.25);padding:8px 26px 8px 10px;font-size:11px;outline:none}.toggle{width:37px;height:21px;border-radius:99px;background:#596159;border:0;padding:3px;cursor:pointer}.toggle span{width:15px;height:15px;border-radius:50%;display:block;background:#e6e1d4;transition:.2s}.toggle.on{background:#a96c49}.toggle.on span{transform:translateX(16px)}.settings-note{font:10px 'DM Mono',monospace;color:#aaaFA1;border-top:1px solid rgba(255,255,255,.14);padding-top:17px;margin-top:5px}.pause-chip{position:absolute;display:none;z-index:4;left:50%;top:50%;transform:translate(-50%,-50%);padding:17px 23px;background:rgba(23,33,29,.88);border:1px solid rgba(255,255,255,.2);font:10px 'DM Mono',monospace;letter-spacing:.15em}.pause-chip.show{display:flex;align-items:center;gap:11px}.pause-chip span{color:#d09a70}.pause-chip button{margin-left:10px;padding:7px 10px;border:1px solid rgba(255,255,255,.35);background:transparent;color:#fff;font:9px 'DM Mono',monospace;letter-spacing:.1em;cursor:pointer}
