import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas = document.querySelector('#scene');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.75));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.14;

const scene = new THREE.Scene();
scene.background = new THREE.Color('#a9b5ad');
scene.fog = new THREE.Fog('#a9b5ad', 130, 510);
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, .1, 900);
const clock = new THREE.Clock();
const hemi = new THREE.HemisphereLight('#e4e6d9', '#69745b', 2.0); scene.add(hemi);
const sun = new THREE.DirectionalLight('#fff0d6', 3.1); sun.position.set(-115, 150, 100); sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024); sun.shadow.camera.left = -180; sun.shadow.camera.right = 180; sun.shadow.camera.top = 180; sun.shadow.camera.bottom = -180; sun.shadow.bias = -.0005; sun.shadow.normalBias = .035; scene.add(sun);

const mat = (color, roughness = .86, extra = {}) => new THREE.MeshStandardMaterial({ color, roughness, ...extra });
const grassMat = mat('#78836a');
const roadMat = mat('#414542', 1);
const shoulderMat = mat('#827e6c');
const lineMat = mat('#d4c8a9', .78);
const darkLineMat = mat('#7b786d', .9);
const ground = new THREE.Mesh(new THREE.PlaneGeometry(1300, 1300), grassMat); ground.rotation.x = -Math.PI / 2; ground.position.y = -.13; ground.receiveShadow = true; scene.add(ground);

const routePoints = [new THREE.Vector3(-4, 0, 145), new THREE.Vector3(2, 0, 86), new THREE.Vector3(22, 0, 43), new THREE.Vector3(67, 0, 12), new THREE.Vector3(112, 0, -6), new THREE.Vector3(136, 0, -52), new THREE.Vector3(119, 0, -104), new THREE.Vector3(67, 0, -132), new THREE.Vector3(9, 0, -123), new THREE.Vector3(-49, 0, -98), new THREE.Vector3(-102, 0, -61), new THREE.Vector3(-125, 0, -15), new THREE.Vector3(-108, 0, 31), new THREE.Vector3(-63, 0, 76), new THREE.Vector3(-34, 0, 116)];
const roadCurve = new THREE.CatmullRomCurve3(routePoints, true, 'catmullrom', .25);
const roadFrames = [];
function makeStrip(width, material, yOffset, segments = 600) {
  const vertices = [], indices = [];
  for (let i = 0; i <= segments; i++) {
    const t = i / segments, p = roadCurve.getPointAt(t), tangent = roadCurve.getTangentAt(t).normalize();
    const side = new THREE.Vector3(tangent.z, 0, -tangent.x).normalize();
    roadFrames.push(i === 0 ? { p: p.clone(), tangent: tangent.clone() } : undefined);
    for (const sign of [-1, 1]) vertices.push(p.x + side.x * width * sign / 2, yOffset, p.z + side.z * width * sign / 2);
    if (i < segments) { const a = i * 2; indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2); }
  }
  const geometry = new THREE.BufferGeometry(); geometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3)); geometry.setIndex(indices); geometry.computeVertexNormals();
  const mesh = new THREE.Mesh(geometry, material); mesh.receiveShadow = true; mesh.frustumCulled = false; scene.add(mesh); return mesh;
}
makeStrip(17.2, shoulderMat, -.025);
makeStrip(14.4, roadMat, .005);
makeStrip(.2, darkLineMat, .013);
// Broken, weathered center markings.
for (let i = 0; i < 154; i++) {
  const t = i / 154, p = roadCurve.getPointAt(t), tangent = roadCurve.getTangentAt(t).normalize();
  const dash = new THREE.Mesh(new THREE.BoxGeometry(.14, .025, 2.4), lineMat);
  dash.position.set(p.x, .035, p.z); dash.rotation.y = Math.atan2(tangent.x, tangent.z); scene.add(dash);
}
// Soft roadside edge lines, deliberately subdued rather than bright.
for (const sideSign of [-1, 1]) {
  const vertices = [], indices = [], N = 600;
  for (let i = 0; i <= N; i++) {
    const p = roadCurve.getPointAt(i / N), t = roadCurve.getTangentAt(i / N).normalize(), side = new THREE.Vector3(t.z, 0, -t.x).normalize();
    for (let j = 0; j < 2; j++) vertices.push(p.x + side.x * sideSign * (6.6 + j * .18), .024, p.z + side.z * sideSign * (6.6 + j * .18));
    if (i < N) { const a = i * 2; indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2); }
  }
  const g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3)); g.setIndex(indices); g.computeVertexNormals(); scene.add(new THREE.Mesh(g, lineMat));
}

// Distant layered hills soften the horizon and frame the valley.
for (let ring = 0; ring < 2; ring++) {
  const hillMat = mat(ring ? '#788671' : '#899681');
  for (let i = 0; i < 15; i++) {
    const a = i / 15 * Math.PI * 2 + ring * .15, r = ring ? 340 : 280;
    const mesh = new THREE.Mesh(new THREE.IcosahedronGeometry(1, 1), hillMat);
    const scale = 50 + ((i * 17 + ring * 9) % 46);
    mesh.position.set(Math.cos(a) * r, 13 + (i % 3) * 4, Math.sin(a) * r - 15); mesh.scale.set(scale * 1.7, scale * .72, scale); mesh.castShadow = false; mesh.receiveShadow = true; scene.add(mesh);
  }
}

const treeMats = ['#495e48', '#58694d', '#657451', '#78805c'].map(c => mat(c));
const trunkMat = mat('#594b39');
function makeTree(x, z, scale = 1, variant = 0) {
  const tree = new THREE.Group(); tree.position.set(x, 0, z); tree.scale.setScalar(scale);
  const trunk = new THREE.Mesh(new THREE.CylinderGeometry(.13, .22, 2.3, 6), trunkMat); trunk.position.y = 1.05; trunk.castShadow = true; tree.add(trunk);
  if (variant % 3 === 0) {
    for (let i = 0; i < 3; i++) { const cone = new THREE.Mesh(new THREE.ConeGeometry(1.05 - i * .16, 2.25, 7), treeMats[(variant + i) % treeMats.length]); cone.position.y = 2.05 + i * .85; cone.castShadow = true; cone.receiveShadow = true; tree.add(cone); }
  } else {
    const crown = new THREE.Mesh(new THREE.IcosahedronGeometry(1.05, 1), treeMats[variant % treeMats.length]); crown.position.y = 3; crown.scale.set(1, 1.12, 1); crown.castShadow = true; crown.receiveShadow = true; tree.add(crown);
  }
  scene.add(tree);
}
let seed = 937;
function rand() { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; }
// Forest ribbons with irregular spacing.
for (let i = 0; i < 175; i++) {
  const t = (i / 175 + rand() * .004) % 1, p = roadCurve.getPointAt(t), tangent = roadCurve.getTangentAt(t), side = new THREE.Vector3(tangent.z, 0, -tangent.x).normalize();
  for (const sign of [-1, 1]) { const d = 13 + rand() * 33; makeTree(p.x + side.x * d * sign, p.z + side.z * d * sign, .7 + rand() * .8, Math.floor(rand() * 7)); }
}
// Far scattered tree groups add a sense of scale without walling in the road.
for (let i = 0; i < 140; i++) { const x = (rand() - .5) * 700, z = (rand() - .5) * 700; if (Math.hypot(x, z) > 160) makeTree(x, z, .65 + rand() * .8, Math.floor(rand() * 7)); }

const wallMats = ['#8c8877', '#aa9e85', '#727c6a', '#b6a58a'].map(c => mat(c));
const roofMats = ['#625f55', '#725c4a', '#555c54'].map(c => mat(c));
function makeHouse(x, z, rotation = 0, scale = 1, kind = 0) {
  const group = new THREE.Group(); group.position.set(x, 0, z); group.rotation.y = rotation; group.scale.setScalar(scale);
  const w = kind === 0 ? 8 : 10, h = kind === 0 ? 4.2 : 5;
  const base = new THREE.Mesh(new THREE.BoxGeometry(w, h, w * .78), wallMats[(kind + Math.floor(rand() * 4)) % 4]); base.position.y = h / 2; base.castShadow = true; base.receiveShadow = true; group.add(base);
  const roof = new THREE.Mesh(new THREE.ConeGeometry(w * .77, 3.2, 4), roofMats[Math.floor(rand() * roofMats.length)]); roof.rotation.y = Math.PI / 4; roof.position.y = h + 1.25; roof.scale.z = .78; roof.castShadow = true; group.add(roof);
  const door = new THREE.Mesh(new THREE.BoxGeometry(1.15, 2.5, .15), mat('#504d42')); door.position.set(0, 1.25, w * .395); group.add(door);
  const windowMat = new THREE.MeshStandardMaterial({ color: '#b7b2a1', roughness: .35, metalness: .05 });
  for (const wx of [-2.4, 2.4]) { const win = new THREE.Mesh(new THREE.BoxGeometry(1.25, 1.1, .12), windowMat); win.position.set(wx, 2.7, w * .395 + .04); group.add(win); }
  group.traverse(o => { if (o.isMesh) o.receiveShadow = true; }); scene.add(group);
}
makeHouse(26, 34, -.34, 1.4, 0); makeHouse(39, 43, .2, 1.1, 1); makeHouse(-21, 33, -.1, 1.05, 0); makeHouse(72, -28, .5, 1.3, 1);
// Rustic fence segments near the settlement.
const fenceMat = mat('#83745c');
for (const [x, z, length] of [[4, 29, 22], [52, 33, 24], [-34, 45, 18]]) {
  for (let i = 0; i <= length; i += 2.3) { const post = new THREE.Mesh(new THREE.BoxGeometry(.12, 1.15, .12), fenceMat); post.position.set(x + i, .55, z); post.castShadow = true; scene.add(post); }
  for (const y of [.42, .84]) { const rail = new THREE.Mesh(new THREE.BoxGeometry(length, .12, .09), fenceMat); rail.position.set(x + length / 2, y, z); scene.add(rail); }
}

const vehicleCatalog = [
  { name: 'FIELD COUPE', desc: 'A little grit. A lot of character.', color: '#a9593e', kind: 'coupe', max: 58, width: 1.88, length: 4.15, height: 1.28 },
  { name: 'TRAIL WAGON', desc: 'Room for the long way around.', color: '#65765c', kind: 'wagon', max: 49, width: 1.94, length: 4.65, height: 1.52 },
  { name: 'RIVER GT', desc: 'Old soul. Open stretches.', color: '#c0a36f', kind: 'gt', max: 66, width: 1.92, length: 4.45, height: 1.22 },
  { name: 'MILEPOST 4X4', desc: 'When the pavement runs out.', color: '#59666a', kind: 'suv', max: 46, width: 2.05, length: 4.25, height: 1.62 }
];
const carRoot = new THREE.Group(); scene.add(carRoot);
let car = new THREE.Group(); carRoot.add(car);
let wheelRoll = [];
let selected = 0;
function box(parent, size, color, pos, options = {}) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(...size), mat(color, options.roughness ?? .52, options)); mesh.position.set(...pos); mesh.castShadow = true; mesh.receiveShadow = true; parent.add(mesh); return mesh;
}
function buildCar(index) {
  const spec = vehicleCatalog[index]; selected = index;
  carRoot.remove(car); car = new THREE.Group(); carRoot.add(car); wheelRoll = [];
  const bodyColor = spec.color;
  const baseY = .6;
  box(car, [spec.width, .47, spec.length], bodyColor, [0, baseY, 0], { roughness: .38, metalness: .18 });
  box(car, [spec.width * .93, .26, spec.length * .72], bodyColor, [0, .85, -.05], { roughness: .4, metalness: .15 });
  const cabinLength = spec.kind === 'wagon' ? 2 : spec.kind === 'suv' ? 1.85 : 1.6;
  const cabin = new THREE.Mesh(new THREE.BoxGeometry(spec.width * .77, spec.height * .57, cabinLength), mat('#343c3a', .36, { metalness: .12 })); cabin.position.set(0, 1.28 + (spec.height - 1.28) * .17, -.22); cabin.castShadow = true; cabin.receiveShadow = true; car.add(cabin);
  const glass = new THREE.Mesh(new THREE.BoxGeometry(spec.width * .72, .42, cabinLength * .76), new THREE.MeshStandardMaterial({ color: '#8b9b99', metalness: .27, roughness: .2, transparent: true, opacity: .76 })); glass.position.set(0, 1.34 + (spec.height - 1.28) * .17, -.19); car.add(glass);
  box(car, [spec.width * .91, .1, .32], '#302f2b', [0, .37, spec.length * .42]);
  box(car, [spec.width * .91, .1, .32], '#302f2b', [0, .37, -spec.length * .42]);
  const headMat = new THREE.MeshStandardMaterial({ color: '#eee1b9', emissive: '#251d11', emissiveIntensity: .3, roughness: .4 });
  for (const x of [-spec.width * .36, spec.width * .36]) {
    const head = new THREE.Mesh(new THREE.BoxGeometry(.33, .16, .08), headMat); head.position.set(x, .78, spec.length * .5); car.add(head);
    const tail = new THREE.Mesh(new THREE.BoxGeometry(.3, .15, .08), mat('#8c4033', .35)); tail.position.set(x, .76, -spec.length * .5); car.add(tail);
  }
  box(car, [spec.width * .44, .1, .06], '#48483e', [0, .65, spec.length * .505]);
  const wheelMat = mat('#252725', .95), hubMat = mat('#9c9788', .43, { metalness: .55 });
  for (const z of [-spec.length * .31, spec.length * .31]) for (const x of [-spec.width * .53, spec.width * .53]) {
    const wheelPivot = new THREE.Group(); wheelPivot.position.set(x, .43, z); car.add(wheelPivot);
    const wheel = new THREE.Mesh(new THREE.CylinderGeometry(.39, .39, .25, 12), wheelMat); wheel.rotation.z = Math.PI / 2; wheel.castShadow = true; wheelPivot.add(wheel);
    const hub = new THREE.Mesh(new THREE.CylinderGeometry(.19, .19, .26, 10), hubMat); hub.rotation.z = Math.PI / 2; wheelPivot.add(hub);
    wheelRoll.push({ wheel, pivot: wheelPivot, front: z > 0 });
  }
  // Simple side mirrors and understated roof trim.
  for (const x of [-1, 1]) { const mirror = new THREE.Mesh(new THREE.BoxGeometry(.24, .12, .23), mat(bodyColor, .45)); mirror.position.set(x * spec.width * .56, 1.12, .65); car.add(mirror); }
  document.querySelector('#car-name').textContent = spec.name;
  document.querySelector('#car-description').textContent = spec.desc;
  document.querySelector('#car-index').textContent = `0${index + 1}`;
  document.querySelector('#swatches').innerHTML = vehicleCatalog.map((v, i) => `<button aria-label="${v.name}" class="swatch" data-car="${i}" style="background:${v.color};${i === index ? 'outline:1px solid #fff;outline-offset:3px' : ''}"></button>`).join('');
